// Turns n8n's error data into one readable alert.
// n8n sends two shapes: `execution` when a step fails mid-run, `trigger` when the trigger itself fails (no run is created).
return $input.all().map(item => {
  const d = item.json;
  const wf = d.workflow || {};
  const ex = d.execution || {};
  const tr = d.trigger || {};
  const err = ex.error || tr.error || {};
  const failedAt = ex.lastNodeExecuted || (err.node && err.node.name) || 'the trigger';
  const message = String(err.message || (err.cause && err.cause.message) || 'No error message').slice(0, 400);
  const lines = [
    `🚨 ${wf.name || 'A workflow'} failed`,
    `Step: ${failedAt}`,
    `Error: ${message}`,
  ];
  if (ex.url) lines.push(`Open the run: ${ex.url}`);
  if (ex.retryOf) lines.push(`This was a retry of run ${ex.retryOf}.`);
  if (!ex.id) lines.push('The trigger failed, so no run was created. Check the trigger step and its login/credentials.');
  return { json: {
    text: lines.join('\n'),
    subject: `n8n: "${wf.name || 'workflow'}" failed at ${failedAt}`,
    workflowName: wf.name || '', failedAt, errorMessage: message, executionUrl: ex.url || '', mode: ex.mode || tr.mode || '',
  } };
});
